uniform float speed : 0.0 .. 3.0 = 1.0;
uniform float scale : 0.5 .. 6.0 = 3.0;
uniform float contrast : 0.0 .. 5.0 = 2.0;
uniform vec3 tint : color = 0.3, 0.6, 1.0;

state fixed ph;

void update() {
  ph = fract(ph + fixed(dt * speed * 0.5));
}

vec3 shade(Led led) {
  fixed x = fixed(led.pos.x) * fixed(scale);
  fixed y = fixed(led.pos.z) * fixed(scale);
  fixed ang = atan2(y, x);
  fixed n = fract(ang * fixed(2.0) + ph);
  fixed bright = clamp((n - fixed(0.45)) * fixed(contrast), fixed(0.0), fixed(1.0));
  bright = bright * bright * fixed(0.8) + fixed(0.2);
  return hsv2rgb(fixed(0.55), fixed(0.9), bright) * vec3(fixed(tint.r), fixed(tint.g), fixed(tint.b));
}

